<?php
session_start();
require_once __DIR__ . '/conexion.php';
if (!isset($_SESSION['usuario'], $_SESSION['rol']) || $_SESSION['rol'] !== 'administrativo') { header('Location: ../HTML/login.html'); exit(); }
$nombre=$_SESSION['nombre'] ?? 'Administrador'; $rol=$_SESSION['rol']; $mensaje=''; $error=false;
function e($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function postInt($k){ return filter_input(INPUT_POST,$k,FILTER_VALIDATE_INT) ?: 0; }
function auditUser(PDO $pdo){ $s=$pdo->prepare('SET @usuario_app = ?'); $s->execute([$_SESSION['usuario']]); }
function friendly(PDOException $e){ $m=$e->getMessage(); if(stripos($m,'Duplicate')!==false) return 'Ya existe un registro con alguno de los datos únicos proporcionados.'; if(stripos($m,'materias requisito')!==false) return 'El alumno no cumple con los prerrequisitos necesarios para esta materia.'; return 'No fue posible completar la operación. Verifica los datos y sus relaciones.'; }
try{if($_SERVER['REQUEST_METHOD']==='POST'){ $a=$_POST['accion']??''; if($a==='estatus'){auditUser($pdo);$s=$pdo->prepare('UPDATE inscripciones SET estatus=? WHERE id=?');$s->execute([$_POST['estatus'],postInt('id')]);$mensaje='Estatus actualizado.';} if($a==='calificacion'){auditUser($pdo);$id=postInt('inscripcion');$vals=[];foreach(['p1','p2','p3'] as $k){$v=trim($_POST[$k]??'');$vals[]=$v===''?null:$v;} $f=(float)($_POST['final']??0);foreach($vals as $v)if($v!==null&&$v!=='N/A'&&(!ctype_digit($v)||(int)$v<70||(int)$v>100))throw new Exception('Los parciales deben ser N/A, vacío o un valor entre 70 y 100.');if($f<0||$f>100)throw new Exception('Calificación final inválida.');$s=$pdo->prepare('INSERT INTO calificaciones(inscripcion,parcial1,parcial2,parcial3,calificacion_final) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE parcial1=VALUES(parcial1),parcial2=VALUES(parcial2),parcial3=VALUES(parcial3),calificacion_final=VALUES(calificacion_final)');$s->execute([$id,...$vals,$f]);$mensaje='Calificación guardada.';} }}catch(PDOException $e){$error=true;$mensaje=friendly($e);}catch(Exception $e){$error=true;$mensaje=$e->getMessage();}$q=trim($_GET['q']??'');$s=$pdo->prepare("SELECT i.id inscripcion,a.nombre alumno,m.nombre materia,g.nombre grupo,pe.nombre periodo,i.estatus,c.parcial1,c.parcial2,c.parcial3,c.calificacion_final FROM inscripciones i JOIN alumnos a ON a.id=i.alumno JOIN materia_profesor mp ON mp.id=i.asignacion JOIN materias m ON m.id=mp.materia JOIN grupos g ON g.id=mp.grupo JOIN periodos_escolares pe ON pe.id=g.id_periodo LEFT JOIN calificaciones c ON c.inscripcion=i.id WHERE a.nombre LIKE ? OR a.correo_institucional LIKE ? ORDER BY a.nombre,pe.fecha_inicio DESC,m.nombre");$s->execute(["%$q%","%$q%"]);$historial=$s->fetchAll();$asistencias=$pdo->query("SELECT asi.fecha,asi.estatus,asi.observaciones,a.nombre alumno,m.nombre materia,g.nombre grupo FROM asistencias asi JOIN inscripciones i ON i.id=asi.inscripcion JOIN alumnos a ON a.id=i.alumno JOIN materia_profesor mp ON mp.id=i.asignacion JOIN materias m ON m.id=mp.materia JOIN grupos g ON g.id=mp.grupo ORDER BY asi.fecha DESC LIMIT 200")->fetchAll();
include __DIR__ . '/../HTML/controlEscolarAdmin.html';
